  void Production(){Sim.DiscoverProcesses();foreach(long n in new long[]{1,10,100,0,-1}){long q=n;Button(n==0?"Buy Max":n==-1?"Next milestone":"Buy "+n,list,()=>{quantity=q;Show();},34);}for(int i=0;i<24;i++){int id=i;var g=GameSession.Content.generators[i];if(!Sim.ProcessDiscovered(i))continue;var row=Box(g.name,list,panel,164);Vertical(row,10,3);var t=Text("",row,16,96);processText[id]=t;var buttons=Box("Actions",row,new Color(0,0,0,0),40);var h=buttons.gameObject.AddComponent<HorizontalLayoutGroup>();h.spacing=8;Button("Buy",buttons,()=>{Sim.Buy(id,quantity==0?Sim.MaxBuy(id):quantity==-1?Sim.NextMilestone(id):quantity);Show();});if(g.input>=0)Button("Reserve",buttons,()=>{int r=g.input;S.reserves[r]=S.reserves[r].Value>0?BigDouble.Zero:BigDouble.Max(1,S.lifetime[r].Value*.1);Show();});}Text("PROCESS UPGRADES",list,23,42);Upgrades(GameSession.Content.upgrades);UpdateProcesses();}
  void UpdateProcesses(){if(S==null)return;Sim.RefreshRates();foreach(var item in processText){int i=item.Key;var g=GameSession.Content.generators[i];var flow=Sim.CachedFlow(i);item.Value.text=g.name+" × "+S.owned[i]+"  •  Cost "+new Number(Sim.Cost(i))+" "+GameSession.Content.resources[g.costResource]+"\nOutput "+new Number(flow)+"/s"+(g.input<0?"":" • Uses "+new Number(Sim.CachedConsumption(i))+" "+GameSession.Content.resources[g.input]+"/s")+"\n"+(S.owned[i]==0?"Not owned. Buy the first unit at the displayed cost.":flow<=0?"Waiting for input. Expand upstream production or release reserves.":"Net "+new Number(Sim.CachedRate(g.output))+"/s • Multiplier ×"+new Number(Sim.CachedProductionMultiplier(i))+" • Milestone in "+Sim.NextMilestone(i));}}
