  void Update(){if(PcActive){UpdatePc();return;}if(back!=null&&back.WasPressedThisFrame()){if(menu)ShowMenu();else{page="Overview";Show();}}if(Screen.width!=previousWidth||Screen.height!=previousHeight){Build();return;}if(Time.unscaledTime<next)return;next=Time.unscaledTime+.5f;var gs=GameSession.Instance;if(gs==null)return;if(!menu&&nav&&S?.offlineReport!=null&&nav.Find("Offline summary")==null)Button("Offline summary",nav,()=>{page="Offline summary";Show();});if(!menu&&S?.offlineReport!=null&&!S.offlineReport.active&&!S.offlineReport.dismissed&&S.offlineReport.processedSeconds>=60&&S.offlineReport.id!=lastOfflineShown){lastOfflineShown=S.offlineReport.id;ShowOfflineDialog();}status.text=(!gs.WebWriter?"READ-ONLY: close the other game tab, then reload. • ":"")+gs.Message+(gs.SaveBusy?" • Saving…":"")+(S!=null&&S.offlineRemaining>1?" • Catching up: "+Math.Floor(S.offlineRemaining)+"s remaining":"");if(S!=null&&!menu){int mask=0;for(int stage=0;stage<6;stage++)if(Sim.StageOpen(stage))mask|=1<<stage;int stamp=mask+S.purchases.Count*64+S.achievements.Count*10000+S.completedChallenges.Count*1000000+S.talents.Count*20000000;if(stamp!=structureStamp){structureStamp=stamp;if(page!="Settings")Show();}balance.text=(AccountBridge.Instance.Owned.supporter?"✦ Supporter · ":"")+string.Join("    ",Enumerable.Range(0,12).Where(i=>S.lifetime[i].Value>0&&(!portrait||i==0||i>=HighestStage()*2)).Select(i=>GameSession.Content.resources[i]+" "+S.resources[i]));UpdateProcesses();foreach(var row in ledgerText)if(row.Value)row.Value.text=GameSession.Content.resources[row.Key]+" • "+S.resources[row.Key]+" • Net "+new Number(Sim.CachedRate(row.Key))+"/s";}}
